function pathsPage(){return pathsPageLocal()+reviewCopiedServicePaths()+reviewSavedPublicPaths()}
function reviewPathBookmarkList(){const list=S.settings.publicPathBookmarks||[];if(!Array.isArray(list)||list.some(p=>!p||typeof p.id!=='string'||typeof p.version!=='string'||typeof p.title!=='string'||!Array.isArray(p.targets)||p.targets.some(t=>!t||typeof t.title!=='string'||typeof t.goal!=='string')))throw Error('路径收藏快照无法核对，原资料保留。');return list}
function reviewPathBookmarkIdentity(p,i){return [S.user.id,reviewAccountGeneration,p.id,p.version,i??''].join('|')}
function reviewPathBookmarkFind(key){const [owner,generation,id,version,index]=key.split('|');if(owner!==S.user?.id||Number(generation)!==reviewAccountGeneration||!reviewContextCurrent(reviewContext()))return null;const p=reviewPathBookmarkList().find(p=>p.id===id&&p.version===version);return p?{p,index:Number(index)}:null}
function reviewSavedPublicPaths(){if(!S.user?.reviewService)return '';try{const list=reviewPathBookmarkList();return list.length?`<section style="margin:18px 0"><h2>收藏的服务路径</h2>${list.map(p=>`<article class="path-card"><h3>${esc(p.title)}</h3><p class="small muted">来源：${esc(p.authorName)} · 收藏版本 ${esc(p.version.slice(0,8))}</p><details><summary>查看收藏时的完整目标顺序</summary>${reviewPathBody(p)}</details><div class="row" style="margin-top:12px">${p.targets.map((t,i)=>btn('查看目标 · '+t.title,'review-bookmarked-target:'+reviewPathBookmarkIdentity(p,i),'ghost')).join('')}${btn('取消这个版本的收藏','review-remove-path-bookmark:'+reviewPathBookmarkIdentity(p),'ghost')}</div></article>`).join('')}</section>`:''}catch(e){return `<p class="error" role="alert">${esc(e.message)}</p>`}}
function reviewRemovePathBookmark(key){try{const found=reviewPathBookmarkFind(key);if(!found)return;S.settings.publicPathBookmarks=reviewPathBookmarkList().filter(p=>p.id!==found.p.id||p.version!==found.p.version);const saved=save();render(false);toast(saved?'已取消这个版本的收藏。':'当前页面已取消，保存尚未确认，请保留备份。')}catch(e){toast(e.message)}}
async function reviewBookmarkPublicPath(p,context,button,status){if(!button.isConnected||button.disabled||!reviewContextCurrent(context))return;button.disabled=true;try{const current=await reviewKnowledgeRequest('/api/review-public-paths/one?id='+encodeURIComponent(p.id),{context});if(!button.isConnected||!reviewContextCurrent(context))return;if(current.ownerId!==context.ownerId||JSON.stringify(current.path)!==JSON.stringify(p))throw Error('路径已变化，请重新读取目录并核对；原收藏保留。');const list=reviewPathBookmarkList();if(!list.some(b=>b.id===p.id&&b.version===p.version))S.settings.publicPathBookmarks=[...list,clone(p)];const saved=save();if(S.page==='paths')render(false);button.textContent='已收藏这个版本';status.textContent=saved?'已保留作者、来源版本和完整目标快照；不复制作者的行动与点亮。':'收藏留在当前页面，保存未确认，请保留备份。'}catch(e){if(button.isConnected&&reviewContextCurrent(context))status.textContent=reviewIsNetworkError(e)?'收藏读取未确认，请重试；原内容保留。':e.message}finally{button.disabled=false}}
function reviewComparablePathTarget(t,kind){const n={...t,kind,nodeId:t.nodeId||t.id};return Object.fromEntries(['kind','treeId','nodeId','originId','title','goal','five','domain','branch','ownership','ownerId','ownerName','version','sourceVersion'].filter(k=>n[k]!==undefined).map(k=>[k,n[k]]))}
async function reviewOpenServicePathTarget(p,index,context=reviewContext()){
 if(!reviewContextCurrent(context)||!Number.isInteger(index)||!p.targets[index])return;modal('<h2>核对路径目标</h2><p id="path-target-loading" role="status">正在核对路径与目标的当前公开版本…</p>','','路径目标');const status=document.getElementById('path-target-loading');
 try{const r=await reviewKnowledgeRequest('/api/review-public-paths/one?id='+encodeURIComponent(p.id),{context});if(!status.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||JSON.stringify(r.path)!==JSON.stringify(p))throw Error('路径已修订，请重新读取并核对新版本；收藏时的原快照保留。');const t=p.targets[index];
  if(t.kind==='personal-public'){const r=await reviewKnowledgeRequest('/api/review-visible-targets/one?nodeId='+encodeURIComponent(t.nodeId),{context});if(!status.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||JSON.stringify(reviewComparablePathTarget(r.target,t.kind))!==JSON.stringify(t))throw Error('目标已变化，请重新核对。');reviewShowVisibleTarget(r.target,context,'',{...clone(p),targetIndex:index});return}
  const n=S.nodes.find(n=>n.id===t.originId);if(!n||n.version!==t.sourceVersion||['title','goal','five','domain','branch','ownership'].some(k=>n[k]!==t[k]))throw Error('本人图谱与路径目标不一致，原收藏保留，请先核对。');closeModal();handle('node-nav:'+n.id);U.reviewPathSelection={...context,target:{nodeId:n.id,nodeGoal:n.goal,nodeVersion:n.version},reference:{...clone(p),targetIndex:index}};await reviewLoadShared(n.id);
 }catch(e){if(status.isConnected&&reviewContextCurrent(context))status.textContent=reviewIsNetworkError(e)?'路径目标读取未确认，请重试；原收藏保留。':e.message}
}
function reviewOpenBookmarkedPathTarget(key){try{const found=reviewPathBookmarkFind(key);if(found)reviewOpenServicePathTarget(found.p,found.index)}catch(e){toast(e.message)}}

function navigate(page){U.reviewPathSelection=null;reviewUpdateAuthorLocation(page);return navigateWithoutPathSelection(page)}
const reviewStartWithoutPathReference=start;
start=function(name,options={}){const selection=U.reviewPathSelection,k=options.knowledge;if(selection&&reviewContextCurrent(selection)&&k&&Object.keys(selection.target).every(key=>k[key]===selection.target[key]))options={...options,knowledge:{...k,pathReference:clone(selection.reference)}};return reviewStartWithoutPathReference(name,options)};
